CREATE OR REPLACE FUNCTION public.guard_purchase_order_ownership() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.digistore_product_id IS DISTINCT FROM OLD.digistore_product_id THEN RAISE EXCEPTION 'Purchase order ownership cannot be reassigned'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_purchase_order_ownership BEFORE UPDATE ON public.digistore24_subscriptions FOR EACH ROW EXECUTE FUNCTION public.guard_purchase_order_ownership();
CREATE OR REPLACE FUNCTION public.refresh_digistore_membership(p_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE selected_plan text; selected_rank integer; product_ids text[]; BEGIN
PERFORM 1 FROM public.user_memberships WHERE user_id=p_user_id FOR UPDATE;
IF EXISTS (SELECT 1 FROM public.user_memberships WHERE user_id=p_user_id AND plan_key <> 'FREE' AND coalesce(cardinality(active_product_ids),0)=0) THEN RETURN; END IF;
SELECT p.plan_key, pl.rank INTO selected_plan,selected_rank FROM public.digistore24_entitlements e JOIN public.digistore24_products p ON p.entitlement_key=e.entitlement_key JOIN public.plans pl ON pl.key=p.plan_key WHERE e.user_id=p_user_id AND e.source='digistore24' AND e.active AND (e.valid_until IS NULL OR e.valid_until>now()) AND p.is_active ORDER BY pl.rank DESC LIMIT 1;
SELECT array_agg(DISTINCT p.digistore_product_id) INTO product_ids FROM public.digistore24_entitlements e JOIN public.digistore24_products p ON p.entitlement_key=e.entitlement_key WHERE e.user_id=p_user_id AND e.source='digistore24' AND e.active AND (e.valid_until IS NULL OR e.valid_until>now()) AND p.is_active;
INSERT INTO public.user_memberships(user_id,plan_key,current_plan,plan_rank,active_product_ids) VALUES(p_user_id,coalesce(selected_plan,'FREE'),coalesce(selected_plan,'FREE'),coalesce(selected_rank,0),coalesce(product_ids,'{}'::text[])) ON CONFLICT(user_id) DO UPDATE SET plan_key=excluded.plan_key,current_plan=excluded.current_plan,plan_rank=excluded.plan_rank,active_product_ids=excluded.active_product_ids,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.refresh_digistore_membership(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_digistore_membership(uuid) TO service_role;